races = {}
for race, cid, name, party, url, rows in ANSWERS:
    src = lambda note, url=url: page(f"iVoterGuide (AFA Action) questionnaire: {note}", url, READ)  # noqa: E731
    races.setdefault(race, []).append({"id": cid, "name": name, "party": party,
                                       "positions": P(*((qid, stance, src(note), None) for qid, stance, note in rows))})

write("data/research/ivoterguide.json",
      [{"id": rid, "partial": True, "candidates": cands} for rid, cands in races.items()],
      "Candidates' own answers to iVoterGuide's questionnaire, read Oct. 27, 2026.", updated=READ)
